1	import { useState, useEffect } from "react";
2	import { useParams, useNavigate, Link } from "react-router-dom";
3	import { useQuery } from "@tanstack/react-query";
4	import { supabase } from "@/integrations/supabase/client";
5	import { Skeleton } from "@/components/ui/skeleton";
6	import { Badge } from "@/components/ui/badge";
7	import { Input } from "@/components/ui/input";
8	import { Briefcase, Layers, Search } from "lucide-react";
9	import JobListingCard from "@/components/career/JobListingCard";
10	
11	interface CareerConfig {
12	  company_name: string;
13	  logo_url: string | null;
14	  brand_color: string;
15	  tagline: string | null;
16	  about: string | null;
17	}
18	
19	interface CareerJob {
20	  id: string;
21	  title: string;
22	  location: string | null;
23	  department: string | null;
24	  employment_type: string | null;
25	  salary_range: string | null;
26	  created_at: string;
27	}
28	
29	export default function CareerPage() {
30	  const { slug } = useParams<{ slug: string }>();
31	  const navigate = useNavigate();
32	  const [selectedDept, setSelectedDept] = useState<string | null>(null);
33	  const [selectedLocation, setSelectedLocation] = useState<string | null>(null);
34	  const [searchQuery, setSearchQuery] = useState("");
35	
36	  const { data, isLoading } = useQuery({
37	    queryKey: ["career-page", slug],
38	    queryFn: async () => {
39	      if (!slug) return null;
40	      const { data, error } = await supabase.rpc("get_career_page", {
41	        p_slug: slug,
42	      });
43	      if (error) throw error;
44	      return data as { config: CareerConfig; jobs: CareerJob[] } | null;
45	    },
46	    enabled: !!slug,
47	    staleTime: 60_000,
48	  });
49	
50	  const config = data?.config;
51	  const jobs = data?.jobs ?? [];
52	  const brandColor = config?.brand_color ?? "#6366f1";
53	
54	  const departments = [
55	    ...new Set(jobs.map((j) => j.department).filter(Boolean)),
56	  ] as string[];
57	  const locations = [
58	    ...new Set(jobs.map((j) => j.location).filter(Boolean)),
59	  ] as string[];
60	
61	  const filteredJobs = jobs.filter((j) => {
62	    if (selectedDept && j.department !== selectedDept) return false;
63	    if (selectedLocation && j.location !== selectedLocation) return false;
64	    if (searchQuery.trim()) {
65	      const q = searchQuery.toLowerCase();
66	      const match =
67	        (j.title ?? "").toLowerCase().includes(q) ||
68	        (j.department ?? "").toLowerCase().includes(q) ||
69	        (j.location ?? "").toLowerCase().includes(q);
70	      if (!match) return false;
71	    }
72	    return true;
73	  });
74	
75	  useEffect(() => {
76	    if (config) {
77	      document.title = `Careers at ${config.company_name} | Rankora`;
78	    }
79	    return () => {
80	      document.title = "Rankora";
81	    };
82	  }, [config]);
83	
84	  const handleApply = (jobId: string) => navigate(`/apply/${jobId}`);
85	
86	  // Loading
87	  if (isLoading) {
88	    return (
89	      <div className="min-h-screen bg-background flex flex-col">
90	        <header className="border-b border-border">
91	          <div className="max-w-4xl mx-auto px-4 py-4 flex items-center gap-3">
92	            <Skeleton className="h-8 w-8 rounded" />
93	            <Skeleton className="h-5 w-32" />
94	          </div>
95	        </header>
96	        <div className="max-w-4xl mx-auto px-4 py-12 w-full space-y-4">
97	          <Skeleton className="h-8 w-64 mx-auto" />
98	          <Skeleton className="h-4 w-48 mx-auto" />
99	          <div className="space-y-4 mt-8">
100	            {[1, 2, 3].map((i) => (
101	              <Skeleton key={i} className="h-24 w-full rounded-xl" />
102	            ))}
103	          </div>
104	        </div>
105	      </div>
106	    );
107	  }
108	
109	  // Not found
110	  if (!config) {
111	    return (
112	      <div className="min-h-screen bg-background flex flex-col">
113	        <header className="border-b border-border">
114	          <div className="max-w-4xl mx-auto px-4 py-4">
115	            <Link
116	              to="/"
117	              className="flex items-center gap-2 text-sm font-semibold"
118	            >
119	              <Layers className="h-5 w-5 text-primary" /> Rankora
120	            </Link>
121	          </div>
122	        </header>
123	        <main className="flex-1 flex items-center justify-center px-4 py-16">
124	          <div className="text-center space-y-4">
125	            <div className="w-14 h-14 rounded-full bg-muted flex items-center justify-center mx-auto">
126	              <Briefcase className="h-7 w-7 text-muted-foreground" />
127	            </div>
128	            <h1 className="text-xl font-semibold">Career page not found</h1>
129	            <p className="text-sm text-muted-foreground">
130	              This career page may have been removed or is not yet active.
131	            </p>
132	            <Link
133	              to="/"
134	              className="text-sm font-medium text-primary hover:text-primary/80 transition-colors"
135	            >
136	              Back to Rankora
137	            </Link>
138	          </div>
139	        </main>
140	      </div>
141	    );
142	  }
143	
144	  // Active career page
145	  return (
146	    <div className="min-h-screen bg-background flex flex-col">
147	      {/* Header */}
148	      <header className="sticky top-0 z-10 bg-background/95 backdrop-blur border-b border-border">
149	        <div className="max-w-4xl mx-auto px-4 py-4 flex items-center gap-3">
150	          {config.logo_url && (
151	            <img
152	              src={config.logo_url}
153	              alt={config.company_name}
154	              className="h-8 w-8 rounded object-cover"
155	            />
156	          )}
157	          <span className="font-semibold text-lg text-foreground">
158	            {config.company_name}
159	          </span>
160	        </div>
161	      </header>
162	
163	      {/* Hero */}
164	      <div className="py-12 px-4" style={{ backgroundColor: brandColor + "0D" }}>
165	        <div className="max-w-4xl mx-auto text-center space-y-3">
166	          <h1 className="text-3xl font-bold text-foreground">
167	            {config.company_name}
168	          </h1>
169	          {config.tagline && (
170	            <p className="text-lg text-muted-foreground">{config.tagline}</p>
171	          )}
172	          {config.about && (
173	            <p className="text-sm text-muted-foreground max-w-2xl mx-auto leading-relaxed mt-2">
174	              {config.about}
175	            </p>
176	          )}
177	          <Badge
178	            variant="secondary"
179	            className="mt-4 text-sm"
180	            style={{ borderColor: brandColor + "40" }}
181	          >
182	            {jobs.length} Open Position{jobs.length !== 1 ? "s" : ""}
183	          </Badge>
184	        </div>
185	      </div>
186	
187	      {/* Search + Filters */}
188	      {jobs.length > 0 && (
189	        <div className="max-w-4xl mx-auto px-4 pt-6 space-y-3">
190	          {/* Search bar */}
191	          <div className="relative">
192	            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground pointer-events-none" />
193	            <Input
194	              placeholder="Search positions..."
195	              value={searchQuery}
196	              onChange={(e) => setSearchQuery(e.target.value)}
197	              className="pl-9 h-10 bg-background"
198	            />
199	          </div>
200	
201	          {/* Filter pills */}
202	          <div className="flex gap-4 flex-wrap">
203	            {/* Department filter */}
204	            {departments.length > 1 && (
205	              <div className="flex gap-1.5 flex-wrap">
206	                <button
207	                  onClick={() => setSelectedDept(null)}
208	                  className={`px-3 py-1.5 rounded-full text-xs font-medium transition-colors ${
209	                    !selectedDept ? "text-white" : "bg-muted text-muted-foreground hover:bg-muted/80"
210	                  }`}
211	                  style={!selectedDept ? { backgroundColor: brandColor } : undefined}
212	                >
213	                  All Depts
214	                </button>
215	                {departments.map((dept) => (
216	                  <button
217	                    key={dept}
218	                    onClick={() => setSelectedDept(dept)}
219	                    className={`px-3 py-1.5 rounded-full text-xs font-medium transition-colors ${
220	                      selectedDept === dept ? "text-white" : "bg-muted text-muted-foreground hover:bg-muted/80"
221	                    }`}
222	                    style={selectedDept === dept ? { backgroundColor: brandColor } : undefined}
223	                  >
224	                    {dept}
225	                  </button>
226	                ))}
227	              </div>
228	            )}
229	
230	            {/* Location filter */}
231	            {locations.length > 1 && (
232	              <div className="flex gap-1.5 flex-wrap">
233	                <button
234	                  onClick={() => setSelectedLocation(null)}
235	                  className={`px-3 py-1.5 rounded-full text-xs font-medium transition-colors ${
236	                    !selectedLocation ? "text-white" : "bg-muted text-muted-foreground hover:bg-muted/80"
237	                  }`}
238	                  style={!selectedLocation ? { backgroundColor: brandColor } : undefined}
239	                >
240	                  All Locations
241	                </button>
242	                {locations.map((loc) => (
243	                  <button
244	                    key={loc}
245	                    onClick={() => setSelectedLocation(loc)}
246	                    className={`px-3 py-1.5 rounded-full text-xs font-medium transition-colors ${
247	                      selectedLocation === loc ? "text-white" : "bg-muted text-muted-foreground hover:bg-muted/80"
248	                    }`}
249	                    style={selectedLocation === loc ? { backgroundColor: brandColor } : undefined}
250	                  >
251	                    {loc}
252	                  </button>
253	                ))}
254	              </div>
255	            )}
256	          </div>
257	
258	          {/* Result count */}
259	          {(searchQuery || selectedDept || selectedLocation) && (
260	            <p className="text-xs text-muted-foreground">
261	              {filteredJobs.length} position{filteredJobs.length !== 1 ? "s" : ""} found
262	            </p>
263	          )}
264	        </div>
265	      )}
266	
267	      {/* Job listings */}
268	      <main className="flex-1 max-w-4xl mx-auto px-4 py-6 w-full">
269	        {filteredJobs.length === 0 ? (
270	          <div className="text-center py-16 space-y-3">
271	            <div className="w-14 h-14 rounded-full bg-muted flex items-center justify-center mx-auto">
272	              <Briefcase className="h-7 w-7 text-muted-foreground/40" />
273	            </div>
274	            <h2 className="text-base font-medium text-foreground">
275	              No open positions right now
276	            </h2>
277	            <p className="text-sm text-muted-foreground">
278	              Check back soon for new opportunities.
279	            </p>
280	          </div>
281	        ) : (
282	          <div className="grid gap-4">
283	            {filteredJobs.map((job) => (
284	              <JobListingCard
285	                key={job.id}
286	                id={job.id}
287	                title={job.title}
288	                location={job.location}
289	                department={job.department}
290	                employmentType={job.employment_type}
291	                salaryRange={job.salary_range}
292	                createdAt={job.created_at}
293	                brandColor={brandColor}
294	                onApply={handleApply}
295	              />
296	            ))}
297	          </div>
298	        )}
299	      </main>
300	
301	      {/* Footer */}
302	      <footer className="py-6 text-center border-t border-border space-y-2">
303	        <p className="text-xs text-muted-foreground">
304	          Powered by{" "}
305	          <Link
306	            to="/"
307	            className="text-primary font-medium hover:text-primary/80 transition-colors"
308	          >
309	            Rankora
310	          </Link>
311	        </p>
312	        <p className="text-[10px] text-muted-foreground/50 max-w-md mx-auto">
313	          By applying, you agree that your information will be processed by the hiring company for recruitment purposes.
314	        </p>
315	      </footer>
316	    </div>
317	  );
318	}
319	
