1	import { useState, useEffect, useRef, useCallback } from "react";
2	import { toast } from "sonner";
3	import { Globe, Copy, ExternalLink, Loader2, Save, Eye } from "lucide-react";
4	import SidebarLayout from "@/components/SidebarLayout";
5	import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
6	import { Button } from "@/components/ui/button";
7	import { Input } from "@/components/ui/input";
8	import { Textarea } from "@/components/ui/textarea";
9	import { Label } from "@/components/ui/label";
10	import { Switch } from "@/components/ui/switch";
11	import { Badge } from "@/components/ui/badge";
12	import { Skeleton } from "@/components/ui/skeleton";
13	import {
14	  Table,
15	  TableBody,
16	  TableCell,
17	  TableHead,
18	  TableHeader,
19	  TableRow,
20	} from "@/components/ui/table";
21	import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
22	import { supabase } from "@/integrations/supabase/client";
23	import { useAuth } from "@/hooks/useAuth";
24	import { useTeam } from "@/hooks/useTeam";
25	
26	// ---------------------------------------------------------------------------
27	// Types
28	// ---------------------------------------------------------------------------
29	
30	interface CareerPageConfig {
31	  id: string;
32	  team_id: string;
33	  company_name: string | null;
34	  slug: string | null;
35	  logo_url: string | null;
36	  brand_color: string | null;
37	  tagline: string | null;
38	  about: string | null;
39	  is_active: boolean;
40	}
41	
42	interface CareerJob {
43	  id: string;
44	  title: string | null;
45	  location: string | null;
46	  department: string | null;
47	  employment_type: string | null;
48	  is_published: boolean | null;
49	  status: string | null;
50	}
51	
52	type SlugStatus = "idle" | "checking" | "available" | "taken";
53	
54	// ---------------------------------------------------------------------------
55	// Helpers
56	// ---------------------------------------------------------------------------
57	
58	function slugify(name: string): string {
59	  const raw = name
60	    .toLowerCase()
61	    .replace(/[^a-z0-9]+/g, "-")
62	    .replace(/^-|-$/g, "")
63	    .slice(0, 60);
64	  // DB constraint requires minimum 3 chars starting and ending with alphanumeric.
65	  // Pad short slugs with a numeric suffix so they always pass the constraint.
66	  if (raw.length < 3) return raw.padEnd(3, "1");
67	  return raw;
68	}
69	
70	// DB constraint only accepts 6-digit hex (#rrggbb).
71	// 3-digit shorthand like #fff is NOT accepted by the career_page_brand_color_format check.
72	function isValidHex(value: string): boolean {
73	  return /^#[0-9A-Fa-f]{6}$/.test(value);
74	}
75	
76	// ---------------------------------------------------------------------------
77	// Skeleton components
78	// ---------------------------------------------------------------------------
79	
80	function ConfigSkeleton() {
81	  return (
82	    <div className="space-y-5">
83	      {[1, 2, 3, 4, 5, 6].map((i) => (
84	        <div key={i} className="space-y-1.5">
85	          <Skeleton className="h-4 w-24" />
86	          <Skeleton className="h-9 w-full" />
87	        </div>
88	      ))}
89	      <Skeleton className="h-9 w-28 mt-2" />
90	    </div>
91	  );
92	}
93	
94	function JobsSkeleton() {
95	  return (
96	    <div className="space-y-0">
97	      {[1, 2, 3].map((i) => (
98	        <div key={i} className="flex items-center gap-4 px-4 py-3 border-b border-border last:border-0">
99	          <Skeleton className="h-4 flex-1" />
100	          <Skeleton className="h-4 w-24" />
101	          <Skeleton className="h-4 w-20" />
102	          <Skeleton className="h-5 w-10 rounded-full" />
103	        </div>
104	      ))}
105	    </div>
106	  );
107	}
108	
109	// ---------------------------------------------------------------------------
110	// Slug status indicator
111	// ---------------------------------------------------------------------------
112	
113	function SlugStatusBadge({ status }: { status: SlugStatus }) {
114	  if (status === "idle") return null;
115	  if (status === "checking") {
116	    return (
117	      <span className="flex items-center gap-1 text-xs text-muted-foreground">
118	        <Loader2 className="h-3 w-3 animate-spin" />
119	        Checking…
120	      </span>
121	    );
122	  }
123	  if (status === "available") {
124	    return (
125	      <Badge variant="outline" className="text-xs border-green-500/50 text-green-600 dark:text-green-400">
126	        Available
127	      </Badge>
128	    );
129	  }
130	  return (
131	    <Badge variant="outline" className="text-xs border-destructive/50 text-destructive">
132	      Already taken
133	    </Badge>
134	  );
135	}
136	
137	// ---------------------------------------------------------------------------
138	// Main page
139	// ---------------------------------------------------------------------------
140	
141	const CareerSettings = () => {
142	  const { user } = useAuth();
143	  const { team } = useTeam();
144	  const queryClient = useQueryClient();
145	
146	  const teamId = team?.id ?? null;
147	  const userId = user?.id ?? null;
148	
149	  // ----- Form state -----
150	  const [companyName, setCompanyName] = useState("");
151	  const [slug, setSlug] = useState("");
152	  const [logoUrl, setLogoUrl] = useState("");
153	  const [brandColor, setBrandColor] = useState("#6366f1");
154	  const [tagline, setTagline] = useState("");
155	  const [about, setAbout] = useState("");
156	  const [isActive, setIsActive] = useState(false);
157	  const [configId, setConfigId] = useState<string | null>(null);
158	  const [isSaving, setIsSaving] = useState(false);
159	  const [slugStatus, setSlugStatus] = useState<SlugStatus>("idle");
160	  const [slugManuallyEdited, setSlugManuallyEdited] = useState(false);
161	  const [togglingJobId, setTogglingJobId] = useState<string | null>(null);
162	
163	  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
164	
165	  // ----- Career page URL -----
166	  const careerPageUrl = slug ? `${window.location.origin}/careers/${slug}` : null;
167	
168	  // ----- Fetch config -----
169	  const { data: configData, isLoading: configLoading } = useQuery({
170	    queryKey: ["career-page-config", teamId],
171	    queryFn: async () => {
172	      if (!teamId) return null;
173	      const { data, error } = await (supabase as any)
174	        .from("career_page_config")
175	        .select("*")
176	        .eq("team_id", teamId)
177	        .maybeSingle();
178	      if (error) throw new Error(error.message);
179	      return data as CareerPageConfig | null;
180	    },
181	    enabled: !!teamId,
182	    staleTime: 60_000,
183	  });
184	
185	  // Populate form when config loads
186	  useEffect(() => {
187	    if (configData) {
188	      setConfigId(configData.id);
189	      setCompanyName(configData.company_name ?? "");
190	      setSlug(configData.slug ?? "");
191	      setLogoUrl(configData.logo_url ?? "");
192	      setBrandColor(configData.brand_color ?? "#6366f1");
193	      setTagline(configData.tagline ?? "");
194	      setAbout(configData.about ?? "");
195	      setIsActive(configData.is_active ?? false);
196	      setSlugManuallyEdited(true); // Don't auto-overwrite on subsequent renders
197	    } else if (!configLoading && team?.name) {
198	      // Pre-fill from team name on first load
199	      setCompanyName(team.name);
200	      const auto = slugify(team.name);
201	      setSlug(auto);
202	    }
203	  }, [configData, configLoading, team?.name]);
204	
205	  // ----- Fetch jobs -----
206	  const { data: jobs = [], isLoading: jobsLoading } = useQuery({
207	    queryKey: ["career-jobs", userId],
208	    queryFn: async () => {
209	      if (!userId) return [];
210	      const { data, error } = await (supabase as any)
211	        .from("jobs")
212	        .select("id, title, location, department, employment_type, is_published, status")
213	        .eq("user_id", userId)
214	        .order("created_at", { ascending: false });
215	      if (error) throw new Error(error.message);
216	      return (data ?? []) as CareerJob[];
217	    },
218	    enabled: !!userId,
219	    staleTime: 30_000,
220	  });
221	
222	  // ----- Slug auto-gen from company name -----
223	  const handleCompanyNameChange = (value: string) => {
224	    setCompanyName(value);
225	    if (!slugManuallyEdited) {
226	      const auto = slugify(value);
227	      setSlug(auto);
228	      triggerSlugCheck(auto);
229	    }
230	  };
231	
232	  // ----- Slug check debounce -----
233	  const triggerSlugCheck = useCallback(
234	    (value: string) => {
235	      if (debounceRef.current) clearTimeout(debounceRef.current);
236	      if (!value || !teamId) {
237	        setSlugStatus("idle");
238	        return;
239	      }
240	      setSlugStatus("checking");
241	      debounceRef.current = setTimeout(async () => {
242	        try {
243	          const { data, error } = await (supabase as any).rpc("is_career_slug_available", {
244	            p_slug: value,
245	            p_team_id: teamId,
246	          });
247	          if (error) throw error;
248	          setSlugStatus(data === true ? "available" : "taken");
249	        } catch {
250	          setSlugStatus("idle");
251	        }
252	      }, 600);
253	    },
254	    [teamId]
255	  );
256	
257	  const handleSlugChange = (value: string) => {
258	    const clean = value.toLowerCase().replace(/[^a-z0-9-]/g, "").slice(0, 60);
259	    setSlug(clean);
260	    setSlugManuallyEdited(true);
261	    triggerSlugCheck(clean);
262	  };
263	
264	  // Cleanup debounce on unmount
265	  useEffect(() => {
266	    return () => {
267	      if (debounceRef.current) clearTimeout(debounceRef.current);
268	    };
269	  }, []);
270	
271	  // ----- Save config -----
272	  const handleSave = async () => {
273	    if (!teamId) {
274	      toast.error("No team found. Create a team first.");
275	      return;
276	    }
277	    if (!companyName.trim()) {
278	      toast.error("Company name is required.");
279	      return;
280	    }
281	    if (!slug.trim()) {
282	      toast.error("URL slug is required.");
283	      return;
284	    }
285	    // DB constraint: ^[a-z0-9][a-z0-9\-]{1,58}[a-z0-9]$ — minimum 3 chars, must start/end with alphanumeric
286	    if (slug.length < 3) {
287	      toast.error("Slug must be at least 3 characters.");
288	      return;
289	    }
290	    if (!/^[a-z0-9]/.test(slug) || !/[a-z0-9]$/.test(slug)) {
291	      toast.error("Slug must start and end with a letter or number.");
292	      return;
293	    }
294	    if (slugStatus === "taken") {
295	      toast.error("That slug is already taken. Choose a different one.");
296	      return;
297	    }
298	
299	    setIsSaving(true);
300	    try {
